<script lang="ts">
 import {invalidateAll} from '$app/navigation';let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();let email=$state(''),role=$state('cellar'),scope=$state<string[]>([]),busy=$state(false),message=$state(''),link=$state('');
 async function create(){busy=true;message='';try{const res=await fetch('/api/invitations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email,role,scope:role==='external'?scope:[]})});const result=await res.json();if(res.ok){link=result.link;message=t(result.mailed?'invitationSent':'shareInvitation');await invalidateAll();}else message=t(result.message);}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
 async function revoke(id:string){busy=true;try{const res=await fetch('/api/invitations',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({id})});message=res.ok?t('saved'):t((await res.json()).message);if(res.ok)await invalidateAll();}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
</script>
<section class="card"><h2>{t('inviteTeam')}</h2><form onsubmit={(e)=>{e.preventDefault();create();}}><label>{t('email')}<input type="email" required bind:value={email} /></label><label>{t('role')}<select bind:value={role}>{#each ['cellar','vineyard','office','oenologist','external','owner'] as r}<option value={r}>{t(r)}</option>{/each}</select></label>{#if role==='external'}<label>{t('scope')}<select multiple bind:value={scope}>{#each model.lots as l}<option value={l.id}>{l.code} · {l.name}</option>{/each}</select></label>{/if}<button disabled={busy}>{t('inviteTeam')}</button></form>{#if link}<label>{t('shareInvitation')}<input readonly value={link} onclick={(e)=>e.currentTarget.select()} /></label>{/if}<p role="status">{message}</p><ul>{#each model.invitations??[] as invite}<li>{invite.email} · {t(invite.role)} · {invite.expires_at}{#if invite.accepted_at} · {t('accepted')}{:else if invite.revoked_at} · {t('revoked')}{:else}<button disabled={busy} onclick={()=>revoke(invite.id)}>{t('revokeInvitation')}</button>{/if}</li>{/each}</ul></section>
<style>form{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));margin:20px 0}li{margin:12px 0}li button{margin-left:12px}input{width:100%}</style>
